/* Only block true telemetry / editor endpoints — NOT framer.com/m/ (icon modules we serve locally). */
const BLOCK = [/events\.framer\.com/, /framer\.com\/edit/, /api\.framer\.com/];
self.addEventListener('install', (e) => self.skipWaiting());
self.addEventListener('activate', (e) => e.waitUntil(self.clients.claim()));
self.addEventListener('fetch', (e) => {
  let url;
  try { url = new URL(e.request.url); } catch { return; }
  if (BLOCK.some((r) => r.test(url.href))) { e.respondWith(new Response('', { status: 204 })); return; }

  // Normalize local requests pointing to assets/ to match original hosts
  let lookupHost = url.host;
  let lookupPath = url.pathname;
  if (url.host === self.location.host) {
    const assetsPrefix = '/assets/';
    const idx = url.pathname.indexOf(assetsPrefix);
    if (idx !== -1) {
      const rest = url.pathname.slice(idx + assetsPrefix.length);
      const parts = rest.split('/');
      if (parts.length > 1) {
        lookupHost = parts[0];
        lookupPath = '/' + parts.slice(1).join('/');
      }
    }
  }

  const key = lookupHost + lookupPath + url.search;
  const local = EXACT[key] || BYPATH[lookupHost + lookupPath];
  if (local) {
    const localUrl = new URL(local, self.registration.scope).href;
    e.respondWith(
      fetch(localUrl)
        .then((response) => {
          // Force correct MIME type for JavaScript modules if served incorrectly by local servers (supports query/version parameters)
          const isJS = /(\.js|\.mjs)(?:@|\?|_|$)/i.test(url.pathname) || /(\.js|\.mjs)(?:@|\?|_|$)/i.test(lookupPath) || /(\.js|\.mjs)(?:@|\?|_|$)/i.test(local);
          if (isJS) {
            const newHeaders = new Headers(response.headers);
            newHeaders.set('Content-Type', 'application/javascript; charset=utf-8');
            return new Response(response.body, {
              status: response.status,
              statusText: response.statusText,
              headers: newHeaders,
            });
          }
          return response;
        })
        .catch(() => fetch(e.request))
    );
    return;
  }
});
